import {
  passesUncounted,
  walksPx
} from "./chunk-YXJKR4QO.js";

// src/edgeWidths.ts
var EDGE_WIDTHS = [
  {
    value: "uniform",
    label: "Uniform",
    description: "Every link the same thickness."
  },
  {
    value: "walks",
    label: "By walks",
    description: "As thick as the passes the walks make along a link, on the linear scale of nodes by walks, so the thicknesses at a fork add up. Uniform while a walk holds nodes not loaded, and in a graph without walks."
  }
];
var drawnEdgeWidth = (graph, edgeWidth) => edgeWidth === "walks" && (!graph.paths?.length || passesUncounted(graph)) ? "uniform" : edgeWidth;
var linkWidthPx = (passes, perPass, edgeWidth, connectorThickness) => edgeWidth === "walks" && perPass > 0 ? walksPx(passes, perPass) : connectorThickness;

export {
  EDGE_WIDTHS,
  drawnEdgeWidth,
  linkWidthPx
};
